def _parse_checkpoint(raw):
    # no trailing newline allowed at all: encoding is compact with no trailing bytes
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError: raise _checkpoint_invalid("is not valid UTF-8")
