    if not isinstance(signature, str): raise TypeError("checkpoint signature must be a str")
    if _HEX64.fullmatch(signature) is None: raise _checkpoint_invalid("signature must be 64 lowercase hex characters")
    payload = data["payload"]
    if not isinstance(payload, dict): raise TypeError("checkpoint payload must be a dict")
    if set(payload.keys()) != _CHECKPOINT_PAYLOAD_KEYS: raise _checkpoint_invalid("payload must contain exactly the keys 'issuer', 'keyVersion', 'lastHash', 'lastSeq', 'moment' and 'version'")
    version = payload["version"]
    if isinstance(version, bool) or not isinstance(version, int): raise TypeError("checkpoint version must be an int")
