def _select_credential(keyring, identity, key_version, moment):
    """Return the usable credential entry for an exact identity/version.

    Keys are selected by exact identity and version with no fallback and
    must be usable *now*: unknown credentials, a revoked, not-yet-valid
    or expired key all raise :class:`AuthenticationError`.
    """
    entry = None
    for candidate in keyring.get(identity, ()):
        if candidate[VERSION] == key_version:
            entry = candidate
            break
    if entry is None:
        raise AuthenticationError(
            f"no credentials for identity {identity!r} and key version {key_version}"
        )
    if entry[REVOKED]:
        raise AuthenticationError(
            f"credentials for identity {identity!r} key version {key_version} are revoked"
        )
    if moment < entry[NOT_BEFORE]:
        raise AuthenticationError(... "are not yet valid")
    if moment > entry[NOT_AFTER]:
        raise AuthenticationError(... "have expired")
    return entry
```

