def make_keyring(secret=SECRET, not_before=0, not_after=10 ** 9, revoked=False):
    return {
        ISSUER: [
            {
                "version": 1,
                "secret": secret,
                "notBefore": not_before,
                "notAfter": not_after,
                "revoked": revoked,
            }
        ]
    }


def make_ticket(
    paths,
    nonce="nonce-1",
    secret=SECRET,
    issuer=ISSUER,
    key_version=1,
    not_before=0,
    not_after=10 ** 9,
):
    payload = {
        "issuer": issuer,
        "keyVersion": key_version,
        "nonce": nonce,
        "notBefore": not_before,
        "notAfter": not_after,
        "paths": list(paths),
    }
    signature = hmac.new(
        bytes.fromhex(secret), compact(payload), hashlib.sha256
    ).hexdigest()
    return compact({"payload": payload, "signature": signature}) + b"\n"


